{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.region_wise_sales AS WITH pincode AS ( SELECT pincode, district, STATENAME, CASE WHEN statename = \'UTTAR PRADESH\' THEN \'UP\' WHEN statename = \'ANDAMAN AND NICOBAR ISLANDS\' THEN \'ANDAMAN\' WHEN statename = \'ANDHRA PRADESH\' THEN \'AP\' WHEN statename = \'ARUNACHAL PRADESH\' THEN \'ARUNACHAL\' WHEN statename = \'HIMACHAL PRADESH\' THEN \'HP\' WHEN statename = \'JAMMU AND KASHMIR\' THEN \'J&K\' WHEN statename = \'MADHYA PRADESH\' THEN \'MP\' WHEN statename = \'WEST BENGAL\' THEN \'WB\' WHEN statename = \'UTTARAKHAND\' THEN \'UK\' WHEN statename = \'THE DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' THEN \'DAMAN\' ELSE STATENAME END AS STATE, CASE WHEN CAST(pincode AS VARCHAR) LIKE \'560%\' OR CAST(pincode AS VARCHAR) LIKE \'562%\' THEN \'BENGALURU\' WHEN CAST(pincode AS VARCHAR) LIKE \'110%\' THEN \'DELHI\' WHEN CAST(pincode AS VARCHAR) LIKE \'4006%\' OR CAST(pincode AS VARCHAR) LIKE \'4007%\' OR CAST(pincode AS VARCHAR) LIKE \'4008%\' OR CAST(pincode AS VARCHAR) LIKE \'4009%\' OR CAST(pincode AS VARCHAR) LIKE \'401%\' OR CAST(pincode AS VARCHAR) LIKE \'421%\' THEN \'THANE\' WHEN CAST(pincode AS VARCHAR) LIKE \'4000%\' OR CAST(pincode AS VARCHAR) LIKE \'4001%\' OR CAST(pincode AS VARCHAR) LIKE \'4002%\' OR CAST(pincode AS VARCHAR) LIKE \'4003%\' OR CAST(pincode AS VARCHAR) LIKE \'4004%\' OR CAST(pincode AS VARCHAR) LIKE \'4005%\' THEN \'MUMBAI\' WHEN CAST(pincode AS VARCHAR) LIKE \'411%\' OR CAST(pincode AS VARCHAR) LIKE \'412%\' THEN \'PUNE\' WHEN CAST(pincode AS VARCHAR) LIKE \'422%\' THEN \'NASHIK\' WHEN CAST(pincode AS VARCHAR) LIKE \'440%\' THEN \'NAGPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'501%\' OR CAST(pincode AS VARCHAR) LIKE \'509%\' THEN \'HYDERABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'502%\' THEN \'HYDERABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'500%\' THEN \'HYDERABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'2013%\' THEN \'NOIDA\' WHEN CAST(pincode AS VARCHAR) LIKE \'2010%\' THEN \'GHAZIABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'226%\' THEN \'LUCKNOW\' WHEN CAST(pincode AS VARCHAR) LIKE \'208%\' THEN \'KANPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'221%\' THEN \'VARANASI\' WHEN CAST(pincode AS VARCHAR) LIKE \'211%\' THEN \'PRAYAGRAJ\' WHEN CAST(pincode AS VARCHAR) LIKE \'122%\' THEN \'GURGAON\' WHEN CAST(pincode AS VARCHAR) LIKE \'121%\' THEN \'FARIDABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'600%\' THEN \'CHENNAI\' WHEN CAST(pincode AS VARCHAR) LIKE \'603%\' OR CAST(pincode AS VARCHAR) LIKE \'631%\' THEN \'KANCHIPURAM\' WHEN CAST(pincode AS VARCHAR) LIKE \'641%\' THEN \'COIMBATORE\' WHEN CAST(pincode AS VARCHAR) LIKE \'682%\' THEN \'COCHIN\' WHEN CAST(pincode AS VARCHAR) LIKE \'695%\' THEN \'THIRUVANANTHAPURAM\' WHEN CAST(pincode AS VARCHAR) LIKE \'302%\' OR CAST(pincode AS VARCHAR) LIKE \'303%\' THEN \'JAIPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'342%\' THEN \'JODHPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'313%\' THEN \'UDAIPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'380%\' THEN \'AHMEDABAD\' WHEN CAST(pincode AS VARCHAR) LIKE \'382%\' THEN \'GANDHINAGAR\' WHEN CAST(pincode AS VARCHAR) LIKE \'395%\' THEN \'SURAT\' WHEN CAST(pincode AS VARCHAR) LIKE \'390%\' THEN \'VADODARA\' WHEN CAST(pincode AS VARCHAR) LIKE \'360%\' THEN \'RAJKOT\' WHEN CAST(pincode AS VARCHAR) LIKE \'452%\' THEN \'INDORE\' WHEN CAST(pincode AS VARCHAR) LIKE \'462%\' THEN \'BHOPAL\' WHEN CAST(pincode AS VARCHAR) LIKE \'800%\' THEN \'PATNA\' WHEN CAST(pincode AS VARCHAR) LIKE \'834%\' THEN \'RANCHI\' WHEN CAST(pincode AS VARCHAR) LIKE \'492%\' THEN \'RAIPUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'751%\' OR CAST(pincode AS VARCHAR) LIKE \'752%\' THEN \'KHORDHA\' WHEN CAST(pincode AS VARCHAR) LIKE \'781%\' THEN \'KAMRUP METRO\' WHEN CAST(pincode AS VARCHAR) LIKE \'575%\' THEN \'MANGALORE\' WHEN CAST(pincode AS VARCHAR) LIKE \'570%\' THEN \'MYSURU\' WHEN CAST(pincode AS VARCHAR) LIKE \'403%\' THEN \'GOA\' WHEN CAST(pincode AS VARCHAR) LIKE \'530%\' THEN \'VISAKHAPATNAM\' WHEN CAST(pincode AS VARCHAR) LIKE \'520%\' OR CAST(pincode AS VARCHAR) LIKE \'521%\' THEN \'KRISHNA\' WHEN CAST(pincode AS VARCHAR) LIKE \'522%\' THEN \'GUNTUR\' WHEN CAST(pincode AS VARCHAR) LIKE \'180%\' THEN \'JAMMU\' WHEN CAST(pincode AS VARCHAR) LIKE \'1403%\' OR CAST(pincode AS VARCHAR) LIKE \'140308%\' OR CAST(pincode AS VARCHAR) LIKE \'160055%\' OR CAST(pincode AS VARCHAR) LIKE \'160059%\' OR CAST(pincode AS VARCHAR) LIKE \'160062%\' THEN \'MOHALI\' WHEN CAST(pincode AS VARCHAR) LIKE \'1600%\' THEN \'CHANDIGARH\' WHEN CAST(pincode AS VARCHAR) LIKE \'711%\' THEN \'KOLKATA\' WHEN CAST(pincode AS VARCHAR) LIKE \'743%\' OR CAST(pincode AS VARCHAR) LIKE \'7001%\' THEN \'KOLKATA\' WHEN CAST(pincode AS VARCHAR) LIKE \'7000%\' THEN \'KOLKATA\' WHEN CAST(pincode AS VARCHAR) LIKE \'141%\' OR CAST(pincode AS VARCHAR) LIKE \'142%\' THEN \'LUDHIANA\' WHEN CAST(pincode AS VARCHAR) LIKE \'248%\' THEN \'DEHRADUN\' ELSE \'Others\' END as city_mapped, latitude, longitude FROM SNITCH_DB.MAPLEMONK.PINCODE_DETAILS_GOV_20251216 WHERE pincode <> \'pincode\' QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode ORDER BY latitude DESC) = 1 ), all_pincodes AS ( SELECT order_timestamp::DATE AS order_date, pincode, SUM(gross_sales) AS sales, count(distinct \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10)) as total_customers FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1,2 ), main AS ( SELECT a.*, b.district, b.statename, b.STATE, b.latitude, b.longitude, b.city_mapped FROM all_pincodes a LEFT JOIN pincode b ON a.pincode = b.pincode ), state_rank AS ( SELECT statename, SUM(sales) AS state_sales, DENSE_RANK() OVER (ORDER BY SUM(sales) DESC) AS state_rank FROM main WHERE statename IS NOT NULL GROUP BY 1 ), city_rank as ( SELECT city_mapped, SUM(sales) AS city_sales, DENSE_RANK() OVER (ORDER BY SUM(sales) DESC) AS city_rank FROM main WHERE city_mapped IS NOT NULL GROUP BY 1 ), state_month_sales AS ( SELECT statename, DATE_TRUNC(\'month\', order_date) AS order_month, SUM(sales) AS state_month_sales FROM main WHERE statename IS NOT NULL GROUP BY 1,2 ), city_month_sales as ( SELECT city_mapped, DATE_TRUNC(\'month\', order_date) AS order_month, SUM(sales) AS city_month_sales FROM main WHERE city_mapped IS NOT NULL GROUP BY 1,2 ), state_month_yoy AS ( SELECT statename, order_month, state_month_sales, LAG(state_month_sales, 12) OVER (PARTITION BY statename ORDER BY order_month) AS last_year_state_month_sales, ROUND( 100 * (state_month_sales - LAG(state_month_sales, 12) OVER (PARTITION BY statename ORDER BY order_month)) / NULLIF(LAG(state_month_sales, 12) OVER (PARTITION BY statename ORDER BY order_month), 0), 2 ) AS state_yoy_growth_pct FROM state_month_sales ), city_month_yoy AS ( SELECT city_mapped, order_month, city_month_sales, LAG(city_month_sales, 12) OVER (PARTITION BY city_mapped ORDER BY order_month) AS last_year_city_month_sales, ROUND( 100 * (city_month_sales - LAG(city_month_sales, 12) OVER (PARTITION BY city_mapped ORDER BY order_month)) / NULLIF(LAG(city_month_sales, 12) OVER (PARTITION BY city_mapped ORDER BY order_month), 0), 2 ) AS city_yoy_growth_pct FROM city_month_sales ), online_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, pincode AS store, order_timestamp::date AS online_acq, sum(gross_sales) as sales FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1,2,3 ), offline_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped AS store, order_date::date AS offline_acq, sum(selling_price) as sales FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' group by 1,2,3 ), combined_acq AS ( SELECT phone_no, online_acq AS order_date, store, sales FROM online_acq UNION ALL SELECT phone_no, offline_acq AS order_date, store, sales FROM offline_acq ), new_sales as ( select phone_no, store, order_date, sum(sales) as sales from combined_acq group by 1,2,3 ), final_acq AS ( SELECT phone_no, MIN(order_date) AS first_order_date FROM combined_acq GROUP BY phone_no ), final_acq_final as ( SELECT f.phone_no, f.first_order_date, c.store, ns.sales FROM final_acq f JOIN combined_acq c ON f.phone_no = c.phone_no AND f.first_order_date = c.order_date left join new_sales ns on f.phone_no = ns.phone_no and c.store = ns.store and f.first_order_date = ns.order_date ), customer_count as ( select store, first_order_date, count(phone_no) as new_customers, sum(sales) as new_customer_sales from final_acq_final group by 1,2 ), final_pre as ( SELECT m.*, sr.state_sales, sr.state_rank, cr.city_sales, cr.city_rank, smy.state_yoy_growth_pct, cmy.city_yoy_growth_pct, ifnull(cc.new_customers,0) as new_customers, ifnull(cc.new_customer_sales,0) as new_customer_sales FROM main m LEFT JOIN state_rank sr ON m.statename = sr.statename LEFT JOIN state_month_yoy smy ON m.statename = smy.statename AND DATE_TRUNC(\'month\', m.order_date) = smy.order_month left join customer_count cc on m.pincode = cc.store and m.order_date = cc.first_order_date left join city_rank cr ON m.city_mapped = cr.city_mapped LEFT JOIN city_month_yoy cmy ON m.city_mapped = cmy.city_mapped AND DATE_TRUNC(\'month\', m.order_date) = cmy.order_month ), new_customers_change_pre as ( SELECT city_mapped, DATE_TRUNC(\'month\', order_date) AS order_month, SUM(new_customers) AS new_customers, sum(total_customers) as total_customers FROM final_pre WHERE city_mapped IS NOT NULL GROUP BY 1,2 ), mom_change_customers as ( SELECT city_mapped, order_month, ROUND( 100 * (new_customers - LAG(new_customers, 12) OVER (PARTITION BY city_mapped ORDER BY order_month)) / NULLIF(LAG(new_customers, 12) OVER (PARTITION BY city_mapped ORDER BY order_month), 0), 2 ) AS city_yoy_new_customers_change_pct, ROUND( 100 * (total_customers - LAG(total_customers, 12) OVER (PARTITION BY city_mapped ORDER BY order_month)) / NULLIF(LAG(total_customers, 12) OVER (PARTITION BY city_mapped ORDER BY order_month), 0), 2 ) AS city_yoy_total_customers_change_pct FROM new_customers_change_pre ) select a.*, b.city_yoy_new_customers_change_pct, b.city_yoy_total_customers_change_pct from final_pre a left join mom_change_customers b on a.city_mapped = b.city_mapped and DATE_TRUNC(\'month\', a.order_date) = b.order_month ; WITH sales AS ( SELECT date_trunc(\'month\', order_date) AS order_month, state, pincode, SUM(sales) AS sales FROM snitch_db.maplemonk.region_wise_sales WHERE state IN (\'KARNATAKA\',\'KERALA\',\'TAMIL NADU\',\'PUDUCHERRY\',\'MAHARASHTRA\',\'DELHI\',\'PUNJAB\',\'HARYANA\',\'GUJARAT\',\'CHANDIGARH\') AND order_date >= \'2025-01-01\' AND order_date < \'2025-11-01\' GROUP BY 1,2,3 ), mom_calc AS ( SELECT order_month, state, pincode, sales, LAG(sales) OVER ( PARTITION BY pincode ORDER BY order_month ) AS prev_month_sales FROM sales ) SELECT order_month, state, pincode, sales, prev_month_sales, ROUND( 100.0 * (sales - prev_month_sales) / NULLIF(prev_month_sales, 0), 2 ) AS mom_growth_pct FROM mom_calc ORDER BY pincode, order_month;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
